export const ROUTE_MS=50000,TUTORIAL_MS=3000,FOLLOW_DELAY_MS=350,ROUTE_SEED=260901,ROOF_Y=.82,CRAFT_RADIUS=.018,AMBER_WIDTH=.03,LEAD_X=.36,FOLLOW_X=.22,MAX_MULTIPLIER=2.5;const S=10,U=.2,D=.13,C=[[0,.44],[15000,.44],[22000,.37],[29000,.49],[35000,.42],[41000,.36],[46000,.48],[50000,.42]],T=[4800,8600,12400,16300,20200,24100,28000,31900,35800,39700,43600,47500],clamp=(v,a,b)=>Math.min(b,Math.max(a,v));function centre(t){t=clamp(t,0,ROUTE_MS);for(let i=1;i<C.length;i++){const[e,v]=C[i];if(t<=e){const[s,p]=C[i-1];return p+(v-p)*(t-s)/(e-s)}}return C.at(-1)[1]}export function corridorAt(elapsed,x=LEAD_X){const t=clamp(elapsed+(x-LEAD_X)*7000,0,ROUTE_MS);return{center:centre(t),half:t<15000?.2:t<35000?.17:.13}}function random(seed){let v=seed>>>0;return()=>((v=(1664525*v+1013904223)>>>0)/4294967296)}export function createRoute(seed=ROUTE_SEED){const next=random(seed);return T.map((at,i)=>{const b=corridorAt(at),inset=at<15000?.025:at<35000?.04:.05;return{id:i+1,at,center:b.center+(next()*2-1)*inset*.75,half:b.half-inset}})}export const GATES=createRoute();export function craftSafety(y,b){if(y+CRAFT_RADIUS>=ROOF_Y)return"red";const edge=Math.abs(y-b.center)+CRAFT_RADIUS;return edge<=b.half?"green":edge<=b.half+AMBER_WIDTH?"amber":"outside"}export function createGame(){return{elapsed:0,accumulator:0,leadY:.44,followerY:.44,held:false,commands:[[-FOLLOW_DELAY_MS,false],[0,false]],score:0,safeMs:0,safeTime:0,chain:0,multiplier:1,gatesCleared:0,gateIndex:0,ended:false,reason:null}}export function setHeld(g,held){held=Boolean(held);if(g.ended||g.held===held)return;g.held=held;g.commands.push([g.elapsed+g.accumulator,held])}function heldAt(commands,time){for(let i=commands.length-1;i>=0;i--)if(commands[i][0]<=time)return commands[i][1];return false}function reset(g){g.chain=0;g.multiplier=1}export function awardGate(g,cleared){if(!cleared)return reset(g);g.chain++;g.multiplier=Math.min(MAX_MULTIPLIER,1+(g.chain-1)*.25);g.gatesCleared++;g.score+=20*g.multiplier}function simulate(g){const t=g.elapsed+S/2,move=(y,held)=>clamp(y+(held?-U:D)*S/1000,.04,.96);g.leadY=move(g.leadY,heldAt(g.commands,t));g.followerY=move(g.followerY,heldAt(g.commands,t-FOLLOW_DELAY_MS));g.elapsed+=S;const a=craftSafety(g.leadY,corridorAt(g.elapsed,LEAD_X)),b=craftSafety(g.followerY,corridorAt(g.elapsed,FOLLOW_X));if(a==="red"||b==="red"){g.ended=true;g.reason="roofline";return}if(a==="green"&&b==="green"){g.safeMs+=S;g.safeTime+=S;if(g.safeMs>=100){g.score+=Math.floor(g.safeMs/100);g.safeMs%=100}}else{g.safeMs=0;reset(g)}while(GATES[g.gateIndex]?.at<=g.elapsed){const gate=GATES[g.gateIndex],inside=y=>Math.abs(y-gate.center)+CRAFT_RADIUS<=gate.half;awardGate(g,a==="green"&&b==="green"&&inside(g.leadY)&&inside(g.followerY));g.gateIndex++}if(g.elapsed>=ROUTE_MS){g.ended=true;g.reason="complete"}}export function updateGame(g,delta){if(g.ended)return g;g.accumulator+=clamp(Number(delta)||0,0,ROUTE_MS);while(g.accumulator>=S&&!g.ended){g.accumulator-=S;simulate(g)}return g}export function summarize(g){return{score:Math.round(g.score),formation:g.elapsed?Math.round(g.safeTime/g.elapsed*100):0,gates:g.gatesCleared,totalGates:GATES.length,breaches:g.reason==="roofline"?1:0,reason:g.reason}}
